COPY INTO DB1.S3.T6
FROM @DB1.S1.STG1/p1/
FILE_FORMAT = (TYPE = CSV SKIP_HEADER = 1)
PATTERN = '.*\.csv';

COPY INTO @DB1.S1.STG1/p2/
FROM (SELECT * FROM DB1.S2.T1)
FILE_FORMAT = (TYPE = PARQUET)
HEADER = TRUE;

PUT file://d1.csv @DB1.S1.STG1/p1/ AUTO_COMPRESS = TRUE;
GET @DB1.S1.STG1/p2/ file://out/;
LIST @DB1.S1.STG1/p1/;
REMOVE @DB1.S1.STG1/p1/d1.csv;
